<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Bouncing Balls in Rotating Hexagon</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body {
            background: #0f1015;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            overflow: hidden;
        }
        canvas {
            display: block;
            box-shadow: 0 0 30px rgba(0, 0, 0, 0.8);
        }
    </style>
</head>
<body>
    <canvas id="canvas"></canvas>

    <script>
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');

        const width = 800;
        const height = 800;
        canvas.width = width;
        canvas.height = height;

        const center = { x: width / 2, y: height / 2 };
        const hexRadius = 300;
        let hexAngle = 0;
        const hexAngularVelocity = 0.45; // Radians per second

        const gravity = 600; // Pixels per second squared
        const restitution = 0.75; // Bounciness factor
        const wallFriction = 0.08; // Tangential friction during wall impact
        const ballFriction = 0.02; // Friction between balls
        const airResistance = 0.9995; // Slight atmospheric drag

        const ballCount = 10;
        const balls = [];

        // Initialize 10 balls with unique vibrant colors
        for (let i = 0; i < ballCount; i++) {
            const angle = (i / ballCount) * Math.PI * 2;
            const dist = 40 + Math.random() * 80;
            balls.push({
                x: center.x + Math.cos(angle) * dist,
                y: center.y + Math.sin(angle) * dist,
                vx: (Math.random() - 0.5) * 80,
                vy: (Math.random() - 0.5) * 80,
                radius: 16,
                mass: 16 * 16,
                color: `hsl(${i * (360 / ballCount)}, 85%, 60%)`
            });
        }

        function getHexagonVertices(angle) {
            const vertices = [];
            for (let i = 0; i < 6; i++) {
                const a = angle + (i * Math.PI / 3);
                vertices.push({
                    x: center.x + hexRadius * Math.cos(a),
                    y: center.y + hexRadius * Math.sin(a)
                });
            }
            return vertices;
        }

        function closestPointOnSegment(px, py, ax, ay, bx, by) {
            const abx = bx - ax;
            const aby = by - ay;
            let t = ((px - ax) * abx + (py - ay) * aby) / (abx * abx + aby * aby);
            t = Math.max(0, Math.min(1, t));
            return { x: ax + t * abx, y: ay + t * aby };
        }

        let lastTime = performance.now();

        function update(dt) {
            const subSteps = 8;
            const sdt = dt / subSteps;

            for (let step = 0; step < subSteps; step++) {
                hexAngle += hexAngularVelocity * sdt;
                const vertices = getHexagonVertices(hexAngle);

                // Update ball positions and velocities with gravity & drag
                for (let b of balls) {
                    b.vy += gravity * sdt;
                    b.vx *= Math.pow(airResistance, sdt * 60);
                    b.vy *= Math.pow(airResistance, sdt * 60);
                    b.x += b.vx * sdt;
                    b.y += b.vy * sdt;
                }

                // Ball-to-wall collisions
                for (let b of balls) {
                    for (let i = 0; i < 6; i++) {
                        const p1 = vertices[i];
                        const p2 = vertices[(i + 1) % 6];
                        const cp = closestPointOnSegment(b.x, b.y, p1.x, p1.y, p2.x, p2.y);

                        const dx = b.x - cp.x;
                        const dy = b.y - cp.y;
                        const dist = Math.hypot(dx, dy);

                        if (dist < b.radius) {
                            let nx = dist === 0 ? 0 : dx / dist;
                            let ny = dist === 0 ? -1 : dy / dist;

                            // Positional correction
                            b.x = cp.x + nx * b.radius;
                            b.y = cp.y + ny * b.radius;

                            // Velocity of the wall at the contact point
                            const rWallX = cp.x - center.x;
                            const rWallY = cp.y - center.y;
                            const vWallX = -hexAngularVelocity * rWallY;
                            const vWallY = hexAngularVelocity * rWallX;

                            // Velocity relative to wall
                            const vrx = b.vx - vWallX;
                            const vry = b.vy - vWallY;

                            const velAlongNormal = vrx * nx + vry * ny;

                            if (velAlongNormal < 0) {
                                const tx = -ny;
                                const ty = nx;
                                const velAlongTangent = vrx * tx + vry * ty;

                                const newNormVel = -velAlongNormal * restitution;
                                const newTangVel = velAlongTangent * (1 - wallFriction);

                                b.vx = vWallX + newNormVel * nx + newTangVel * tx;
                                b.vy = vWallY + newNormVel * ny + newTangVel * ty;
                            }
                        }
                    }
                }

                // Ball-to-ball collisions
                for (let i = 0; i < balls.length; i++) {
                    for (let j = i + 1; j < balls.length; j++) {
                        const b1 = balls[i];
                        const b2 = balls[j];

                        const dx = b2.x - b1.x;
                        const dy = b2.y - b1.y;
                        const dist = Math.hypot(dx, dy);
                        const minDist = b1.radius + b2.radius;

                        if (dist < minDist && dist > 0) {
                            const nx = dx / dist;
                            const ny = dy / dist;

                            // Separate balls to prevent overlap
                            const overlap = 0.5 * (minDist - dist);
                            b1.x -= nx * overlap;
                            b1.y -= ny * overlap;
                            b2.x += nx * overlap;
                            b2.y += ny * overlap;

                            // Relative velocity along normal
                            const vrx = b2.vx - b1.vx;
                            const vry = b2.vy - b1.vy;
                            const velAlongNormal = vrx * nx + vry * ny;

                            if (velAlongNormal < 0) {
                                const impulse = -(1 + restitution) * velAlongNormal / (1 / b1.mass + 1 / b2.mass);
                                b1.vx -= (impulse / b1.mass) * nx;
                                b1.vy -= (impulse / b1.mass) * ny;
                                b2.vx += (impulse / b2.mass) * nx;
                                b2.vy += (impulse / b2.mass) * ny;

                                // Tangential friction
                                const tx = -ny;
                                const ty = nx;
                                const velAlongTangent = vrx * tx + vry * ty;
                                const tangentImpulse = -velAlongTangent * ballFriction;
                                b1.vx -= (tangentImpulse / b1.mass) * tx;
                                b1.vy -= (tangentImpulse / b1.mass) * ty;
                                b2.vx += (tangentImpulse / b2.mass) * tx;
                                b2.vy += (tangentImpulse / b2.mass) * ty;
                            }
                        }
                    }
                }
            }
        }

        function draw() {
            ctx.clearRect(0, 0, width, height);

            const vertices = getHexagonVertices(hexAngle);

            // Hexagon fill background
            ctx.beginPath();
            ctx.moveTo(vertices[0].x, vertices[0].y);
            for (let i = 1; i < 6; i++) {
                ctx.lineTo(vertices[i].x, vertices[i].y);
            }
            ctx.closePath();
            ctx.fillStyle = '#161923';
            ctx.fill();

            // Hexagon glowing outline
            ctx.lineWidth = 5;
            ctx.strokeStyle = '#4e8cff';
            ctx.shadowBlur = 15;
            ctx.shadowColor = '#4e8cff';
            ctx.stroke();
            ctx.shadowBlur = 0;

            // Draw balls
            for (let b of balls) {
                ctx.save();
                ctx.beginPath();
                ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);

                const grad = ctx.createRadialGradient(
                    b.x - b.radius * 0.3,
                    b.y - b.radius * 0.3,
                    b.radius * 0.1,
                    b.x,
                    b.y,
                    b.radius
                );
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.3, b.color);
                grad.addColorStop(1, '#000000');

                ctx.fillStyle = grad;
                ctx.fill();
                ctx.restore();
            }
        }

        function loop(timestamp) {
            const dt = Math.min((timestamp - lastTime) / 1000, 0.033);
            lastTime = timestamp;

            update(dt);
            draw();

            requestAnimationFrame(loop);
        }

        requestAnimationFrame((timestamp) => {
            lastTime = timestamp;
            requestAnimationFrame(loop);
        });
    </script>
</body>
</html>
